{"version":3,"file":"doctor.js","sources":["api/doctor.ts"],"sourcesContent":["import { http } from '../utils/request';\nconst PREFIX = '/doctor';\n\nconst d = {\n  get: (path: string, params?: any, options?: any) => http.get(`${PREFIX}${path}`, params, options),\n  post: (path: string, data?: any, options?: any) => http.post(`${PREFIX}${path}`, data, options),\n  put: (path: string, data?: any, options?: any) => http.put(`${PREFIX}${path}`, data, options),\n  delete: (path: string, params?: any, options?: any) => http.delete(`${PREFIX}${path}`, params, options),\n};\n\n// 方法：规范化服务端返回，空数组 -> 空对象，数组 -> 首元素\nfunction normalizeOne<T>(data: T | T[]): T {\n  if (Array.isArray(data)) {\n    return (data[0] ?? ({} as T)) as T;\n  }\n  return data as T;\n}\n\nexport interface Schedule {\n  id: number;\n  date: string;\n  timeRange: string;\n  roomNo: string;\n  totalSlots: number;\n  bookedCount: number;\n}\n\nexport interface ShiftApply {\n  doctorId: number\n  originalScheduleId: number\n  targetDate: string\n  targetTimeSlot: number\n  targetDeptId: number\n  reason: string\n}\n\nexport const doctorApi = {\n  // 获取未来 N 天排班\n  getSchedules: (doctorId: number, startDate: string, days: number) =>\n    d.get('/schedules', { doctorId, startDate, days }),\n\n  // 获取今日排班\n  getTodaySchedule: (doctorId: number) =>\n    d.get('/schedule/today', { doctorId }),\n\n  // 申请调班（后端：/doctor/shift-change/apply）\n  applyShiftChange: (data: ShiftApply) =>\n    d.post('/shift-change/apply', data),\n\n  // 查询我的调班申请（后端：/doctor/shift-change/list）\n  listShiftChange: (doctorId: number, status?: number) =>\n    d.get('/shift-change/list', { doctorId, status }),\n\n  // 按日期获取患者列表\n  getPatientsByDate: (doctorId: number, date: string) =>\n    d.get('/patients/by-date', { doctorId, date }),\n\n  // 患者详情\n  getPatientDetail: (patientId: number) =>\n    d.get(`/patient/${patientId}`),\n\n  // 更新就诊状态（开始接诊/完成接诊）\n  updatePatientStatus: (appointmentId: number, action: 'start' | 'finish') =>\n    d.post('/patient/status', { appointmentId, action }),\n\n  // 会话接口（依赖后端 /doctor/profile/me）\n  getMyProfile: () =>\n    d.get('/profile/me').then((res) => normalizeOne<any>(res)),\n};"],"names":["http"],"mappings":";;AACA,MAAM,SAAS;AAEf,MAAM,IAAI;AAAA,EACR,KAAK,CAAC,MAAc,QAAc,YAAkBA,cAAAA,KAAK,IAAI,GAAG,MAAM,GAAG,IAAI,IAAI,QAAQ,OAAO;AAAA,EAChG,MAAM,CAAC,MAAc,MAAY,YAAkBA,cAAAA,KAAK,KAAK,GAAG,MAAM,GAAG,IAAI,IAAI,MAAM,OAAO;AAAA,EAC9F,KAAK,CAAC,MAAc,MAAY,YAAkBA,cAAAA,KAAK,IAAI,GAAG,MAAM,GAAG,IAAI,IAAI,MAAM,OAAO;AAAA,EAC5F,QAAQ,CAAC,MAAc,QAAc,YAAkBA,cAAAA,KAAK,OAAO,GAAG,MAAM,GAAG,IAAI,IAAI,QAAQ,OAAO;AACxG;AAGA,SAAS,aAAgB,MAAkB;AACrC,MAAA,MAAM,QAAQ,IAAI,GAAG;AACf,WAAA,KAAK,CAAC,KAAM;EACtB;AACO,SAAA;AACT;AAoBO,MAAM,YAAY;AAAA;AAAA,EAEvB,cAAc,CAAC,UAAkB,WAAmB,SAClD,EAAE,IAAI,cAAc,EAAE,UAAU,WAAW,KAAA,CAAM;AAAA;AAAA,EAGnD,kBAAkB,CAAC,aACjB,EAAE,IAAI,mBAAmB,EAAE,UAAU;AAAA;AAAA,EAGvC,kBAAkB,CAAC,SACjB,EAAE,KAAK,uBAAuB,IAAI;AAAA;AAAA,EAGpC,iBAAiB,CAAC,UAAkB,WAClC,EAAE,IAAI,sBAAsB,EAAE,UAAU,QAAQ;AAAA;AAAA,EAGlD,mBAAmB,CAAC,UAAkB,SACpC,EAAE,IAAI,qBAAqB,EAAE,UAAU,MAAM;AAAA;AAAA,EAG/C,kBAAkB,CAAC,cACjB,EAAE,IAAI,YAAY,SAAS,EAAE;AAAA;AAAA,EAG/B,qBAAqB,CAAC,eAAuB,WAC3C,EAAE,KAAK,mBAAmB,EAAE,eAAe,QAAQ;AAAA;AAAA,EAGrD,cAAc,MACZ,EAAE,IAAI,aAAa,EAAE,KAAK,CAAC,QAAQ,aAAkB,GAAG,CAAC;AAC7D;;"}
