{"version":3,"file":"doctor.js","sources":["api/doctor.ts"],"sourcesContent":["import { http } from '../utils/request';\r\nconst PREFIX = '/doctor';\r\n\r\nconst d = {\r\n  get: (path: string, params?: any, options?: any) => http.get(`${PREFIX}${path}`, params, options),\r\n  post: (path: string, data?: any, options?: any) => http.post(`${PREFIX}${path}`, data, options),\r\n  put: (path: string, data?: any, options?: any) => http.put(`${PREFIX}${path}`, data, options),\r\n  delete: (path: string, params?: any, options?: any) => http.delete(`${PREFIX}${path}`, params, options),\r\n};\r\n\r\n// 方法：规范化服务端返回，空数组 -> 空对象，数组 -> 首元素\r\nfunction normalizeOne<T>(data: T | T[]): T {\r\n  if (Array.isArray(data)) {\r\n    return (data[0] ?? ({} as T)) as T;\r\n  }\r\n  return data as T;\r\n}\r\n\r\nexport interface Schedule {\r\n  id: number;\r\n  date: string;\r\n  timeRange: string;\r\n  roomNo: string;\r\n  totalSlots: number;\r\n  bookedCount: number;\r\n}\r\n\r\nexport interface ShiftApply {\r\n  doctorId: number\r\n  originalScheduleId: number\r\n  targetDate: string\r\n  targetTimeSlot: number\r\n  targetDeptId: number\r\n  reason: string\r\n}\r\n\r\nexport const doctorApi = {\r\n  // 获取未来 N 天排班\r\n  getSchedules: (doctorId: number, startDate: string, days: number) =>\r\n    d.get('/schedules', { doctorId, startDate, days }),\r\n\r\n  // 获取今日排班\r\n  getTodaySchedule: (doctorId: number) =>\r\n    d.get('/schedule/today', { doctorId }),\r\n\r\n  // 申请调班（后端：/doctor/shift-change/apply）\r\n  applyShiftChange: (data: ShiftApply) =>\r\n    d.post('/shift-change/apply', data),\r\n\r\n  // 查询我的调班申请（后端：/doctor/shift-change/list）\r\n  listShiftChange: (doctorId: number, status?: number) =>\r\n    d.get('/shift-change/list', { doctorId, status }),\r\n\r\n  // 按日期获取患者列表\r\n  getPatientsByDate: (doctorId: number, date: string) =>\r\n    d.get('/patients/by-date', { doctorId, date }),\r\n\r\n  // 患者详情\r\n  getPatientDetail: (patientId: number) =>\r\n    d.get(`/patient/${patientId}`),\r\n\r\n  // 更新就诊状态（已接诊/已完成）\r\n  updatePatientStatus: (appointmentId: number, status: 'RECEIVED' | 'DONE') =>\r\n    d.post('/patient/status', { appointmentId, status }),\r\n\r\n  // 按 userId 查询医生资料（依赖后端 /doctor/profile/byUserId）\r\n  getProfileByUserId: (userId: number) =>\r\n    d.get('/profile/byUserId', { userId }).then((res) => normalizeOne<any>(res)),\r\n\r\n  // 会话接口（依赖后端 /doctor/profile/me）\r\n  getMyProfile: () =>\r\n    d.get('/profile/me').then((res) => normalizeOne<any>(res)),\r\n};"],"names":["http"],"mappings":";;AACA,MAAM,SAAS;AAEf,MAAM,IAAI;AAAA,EACR,KAAK,CAAC,MAAc,QAAc,YAAkBA,cAAAA,KAAK,IAAI,GAAG,MAAM,GAAG,IAAI,IAAI,QAAQ,OAAO;AAAA,EAChG,MAAM,CAAC,MAAc,MAAY,YAAkBA,cAAAA,KAAK,KAAK,GAAG,MAAM,GAAG,IAAI,IAAI,MAAM,OAAO;AAAA,EAC9F,KAAK,CAAC,MAAc,MAAY,YAAkBA,cAAAA,KAAK,IAAI,GAAG,MAAM,GAAG,IAAI,IAAI,MAAM,OAAO;AAAA,EAC5F,QAAQ,CAAC,MAAc,QAAc,YAAkBA,cAAAA,KAAK,OAAO,GAAG,MAAM,GAAG,IAAI,IAAI,QAAQ,OAAO;AACxG;AAGA,SAAS,aAAgB,MAAkB;AACrC,MAAA,MAAM,QAAQ,IAAI,GAAG;AACf,WAAA,KAAK,CAAC,KAAM;EACtB;AACO,SAAA;AACT;AAoBO,MAAM,YAAY;AAAA;AAAA,EAEvB,cAAc,CAAC,UAAkB,WAAmB,SAClD,EAAE,IAAI,cAAc,EAAE,UAAU,WAAW,KAAA,CAAM;AAAA;AAAA,EAGnD,kBAAkB,CAAC,aACjB,EAAE,IAAI,mBAAmB,EAAE,UAAU;AAAA;AAAA,EAGvC,kBAAkB,CAAC,SACjB,EAAE,KAAK,uBAAuB,IAAI;AAAA;AAAA,EAGpC,iBAAiB,CAAC,UAAkB,WAClC,EAAE,IAAI,sBAAsB,EAAE,UAAU,QAAQ;AAAA;AAAA,EAGlD,mBAAmB,CAAC,UAAkB,SACpC,EAAE,IAAI,qBAAqB,EAAE,UAAU,MAAM;AAAA;AAAA,EAG/C,kBAAkB,CAAC,cACjB,EAAE,IAAI,YAAY,SAAS,EAAE;AAAA;AAAA,EAG/B,qBAAqB,CAAC,eAAuB,WAC3C,EAAE,KAAK,mBAAmB,EAAE,eAAe,QAAQ;AAAA;AAAA,EAGrD,oBAAoB,CAAC,WACnB,EAAE,IAAI,qBAAqB,EAAE,OAAQ,CAAA,EAAE,KAAK,CAAC,QAAQ,aAAkB,GAAG,CAAC;AAAA;AAAA,EAG7E,cAAc,MACZ,EAAE,IAAI,aAAa,EAAE,KAAK,CAAC,QAAQ,aAAkB,GAAG,CAAC;AAC7D;;"}
